  [ [[old-11]] ] = { t = [[正能量与负能量]], q = [[正能量和负能量这两个词出现在各种能力里，但除了这些能力之外它们没有定义，而且这些能力的说法也并不总是一致。正能量和负能量究竟是如何起作用的？]], a = [=[正能量和负能量是两种伤害类型，不过尽管名字如此，它们通常不在[[抵抗能量伤害]]之类法术或[[元素法术]]之类专长可选的能量类型列表中。你有时会看到“造成X点伤害；这是负能量效果”的说法，有时会看到“造成X点负能量伤害”的说法，两者在功能上是等价的。

正能量通常治疗活物，但并非总是如此（例如用来伤害不死生物的[[引导能量|引导正能量]]，或[[生命暴发]]法术）。它通常伤害[[不死生物]]，但也并非总是如此（例如用来治疗活物的引导正能量）。具体的效果会说明它们是治疗活物（如果只提到治疗而没有指明治疗对象，指的总是仅限活物）、伤害不死生物，还是两者皆有。正能量绝不会治疗或伤害既非活物也非不死生物的生物或物体（例如[[构装体]]），也绝不会直接伤害活物或治疗不死生物，除非有明文改变这一点的特殊效果，例如[[吸血裔]]的[[负能量亲和]]。这些规则同样适用于[[位面特性#正能量主导|正能量主导位面]]提供的快速治疗（不过在强正能量主导位面上过度治疗同样可能有危险）；在这类位面上，只有活物获得快速治疗。

负能量的作用与上述正能量完全相同，只是在所有情况下活物与不死生物互换（它通常治疗不死生物，通常伤害活物；如果只提到伤害而没有指明伤害对象，指的总是仅限活物，以此类推）。]=], book = [[核心规则书]], date = [[]], paizo = [[]], cat = [[FAQ]], ai = true, pages = { [[魔法]], [[牧师]], [[位面特性]] } },
